namespace sv_40f3d7e7e02c4836882229eadee0ee7a.Services;

/// <summary>
/// Scoped service that polls for low-stock item counts and notifies all subscribers.
/// Each circuit gets its own instance, so concurrent users are fully isolated.
/// </summary>
public class InventoryAlertService : IDisposable
{
    private readonly WarehouseState _warehouseState;
    private readonly Random _random = new();
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _subscriberCount;

    public int LowStockCount { get; private set; }

    /// <summary>
    /// Fired from a background thread — subscribers must wrap StateHasChanged in InvokeAsync.
    /// </summary>
    public event Action? OnAlertCountChanged;

    public InventoryAlertService(WarehouseState warehouseState)
    {
        _warehouseState = warehouseState;
    }

    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulates a database query
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Called by components that want polling active. Polling starts on the first
    /// subscriber and stops when the last one unsubscribes.
    /// </summary>
    public void StartPolling()
    {
        _subscriberCount++;
        if (_subscriberCount == 1)
        {
            _cts = new CancellationTokenSource();
            _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
            _ = PollLoopAsync(_cts.Token);
        }
    }

    public void StopPolling()
    {
        _subscriberCount = Math.Max(0, _subscriberCount - 1);
        if (_subscriberCount == 0)
        {
            _cts?.Cancel();
            _timer?.Dispose();
            _timer = null;
            _cts?.Dispose();
            _cts = null;
        }
    }

    /// <summary>
    /// Force an immediate refresh (e.g. when the warehouse changes).
    /// </summary>
    public async Task RefreshAsync()
    {
        LowStockCount = await GetLowStockCountAsync(_warehouseState.Current.Id);
        OnAlertCountChanged?.Invoke();
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        // Fire immediately on start so the UI isn't blank until the first tick.
        await RefreshAsync();

        while (!ct.IsCancellationRequested)
        {
            try
            {
                if (_timer is null || !await _timer.WaitForNextTickAsync(ct))
                    break;

                await RefreshAsync();
            }
            catch (OperationCanceledException)
            {
                break;
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _timer?.Dispose();
        _cts?.Dispose();
    }
}

