@inject Services.WarehouseState WarehouseState
@inject Services.InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<div class="d-flex align-items-center gap-2">
    <label class="form-label mb-0 text-white" for="warehouse-select">Warehouse:</label>
    <select id="warehouse-select"
            class="form-select form-select-sm"
            style="width: auto;"
            value="@WarehouseState.Current.Id"
            @onchange="OnWarehouseChanged">
        @foreach (var wh in Services.WarehouseState.AvailableWarehouses)
        {
            <option value="@wh.Id">@wh.Name</option>
        }
    </select>
</div>

@code {
    private async Task OnWarehouseChanged(ChangeEventArgs e)
    {
        var id = e.Value?.ToString();
        if (!string.IsNullOrEmpty(id))
        {
            WarehouseState.SetWarehouse(id);
            // Refresh alerts immediately for the new warehouse.
            await AlertService.RefreshAsync();
        }
    }

    // The selector also listens for external warehouse changes (defensive).
    protected override void OnInitialized()
    {
        WarehouseState.OnChange += HandleStateChanged;
    }

    private void HandleStateChanged() => InvokeAsync(StateHasChanged);

    public void Dispose()
    {
        WarehouseState.OnChange -= HandleStateChanged;
    }
}

@inject Services.InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

@if (AlertService.LowStockCount > 0)
{
    <span class="badge bg-danger rounded-pill">@AlertService.LowStockCount</span>
}
else
{
    <span class="badge bg-success rounded-pill">0</span>
}

@code {
    private Action? _handler;

    protected override void OnInitialized()
    {
        // Timer fires from a background thread, so wrap in InvokeAsync.
        _handler = () => InvokeAsync(StateHasChanged);
        AlertService.OnAlertCountChanged += _handler;
    }

    public void Dispose()
    {
        AlertService.OnAlertCountChanged -= _handler;
    }
}

@page "/dashboard"
@inject Services.WarehouseState WarehouseState
@inject Services.InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<PageTitle>Dashboard — @WarehouseState.Current.Name</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mt-3" style="max-width: 30rem;">
    <div class="card-header d-flex justify-content-between align-items-center">
        <span>@WarehouseState.Current.Name — Inventory Alerts</span>
        <AlertBadge />
    </div>
    <div class="card-body">
        @if (AlertService.LowStockCount > 0)
        {
            <p class="text-danger">
                ⚠ <strong>@AlertService.LowStockCount</strong> item(s) are below minimum stock levels.
            </p>
        }
        else
        {
            <p class="text-success">✓ All items are at or above minimum stock levels.</p>
        }
        <p class="text-muted mb-0">
            Polling every 10 seconds. Last checked: @_lastChecked.ToString("T")
        </p>
    </div>
</div>

@code {
    private DateTime _lastChecked = DateTime.Now;
    private Action? _alertHandler;
    private Action? _warehouseHandler;

    protected override void OnInitialized()
    {
        // Start polling when dashboard is visible.
        AlertService.StartPolling();

        _alertHandler = () => InvokeAsync(() =>
        {
            _lastChecked = DateTime.Now;
            StateHasChanged();
        });
        AlertService.OnAlertCountChanged += _alertHandler;

        _warehouseHandler = () => InvokeAsync(StateHasChanged);
        WarehouseState.OnChange += _warehouseHandler;
    }

    public void Dispose()
    {
        // Stop polling when the user leaves the page.
        AlertService.StopPolling();
        AlertService.OnAlertCountChanged -= _alertHandler;
        WarehouseState.OnChange -= _warehouseHandler;
    }
}

